INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Keine Creme hat bisher gegen die Trockenen Stellen geholfen ohne dann auch alles glänzen zu lassen, meine Herbsom Creme hat das Problem behoben. Habe die 2. bestellt, die erste hielt gute 6 Monate bei 1x täglich und damit ist sie sogar gar nicht so teuer im Vergleich zu anderen, aber dabei so viel besser.', 'Liesa Demtröder', 'ldemtroeder@web.de', 'approved', '2022-08-26 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Hallo liebes Herbsom-Team, ich  in total  begeistert, meine Haut fühlt sich richtig gut versorgt  an. Benutze eure Creme vom ersten Tag an. Sagt doch wohl alles. Macht weiter. Wünsche euch viel Erfolg. Eure Heike', 'Heike Bantelmann', 'hbtm@web.de', 'approved', '2022-10-02 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Ich bin begeistert und sprachlos! Liebe meine Creme sehr!', 'Kathrin Fesenmeyer', 'kathrin.fesenmeyer@t-online.de', 'approved', '2022-08-08 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Ich liebe diese Creme! Absolut tolles Hautgefühl. Ich hatte vorher Unreinheiten und Pickel und das Gefühl, dass meine Haut sich damit nicht mehr selbst helfen konnte. Jetzt fühlt sich meine Hautbarriere wieder gestärkt an und meine Haut ist reiner geworden. Riesengroßes Dankeschön!🤍💆🏼', 'Alica Klemm', 'alica.klemm@gmail.com', 'approved', '2022-07-31 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Die Creme ist angenehm aufzutragen, zieht sehr schnell ein und die Haut fühlt sich sehr gut an. Ich habe sie wegen meiner Rötungen bestellt, da hat sich leider noch nichts getan…aber ich glaube, das geht nicht so schnell', 'Kerstin Schmidt', 'schmidt-kerstin@web.de', 'approved', '2022-07-14 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Meine persönliche Herbsom Creme passt perfekt zu mir! Ich habe endlich das Gefühl die Kontrolle über meine Haut zurück gewonnen zu haben :)
Außerdem funktioniert die Creme super unter Make-Up und hinterlässt ein angenehmes Hautgefühl.
Großes Lob an das gesamte Team !!', 'Pelin Cengiz', 'pelincengiz@hotmail.de', 'approved', '2022-05-26 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Liebes Herbsom-Team, 
ich bin ein super Fan von eurer Creme und empfehle sie schon meinen ganzen Freunden weiter. Meine Haut ist wirklich viel besser geworden und ständig werde ich auf meinen natürlichen Glow angesprochen. Auf jeden Fall eine Herzensempfehlung !!! <3', 'Leonie Welters', 'weltersleonie@gmail.com', 'approved', '2022-05-26 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Die Creme hat mich wirklich überzeugt. Ich hatte unter anderem Probleme mit Unreinheiten in der Tzone, die ich jetzt nicht mehr habe. Außerdem bietet es mir die Möglichkeit, verschiedene Wirkungen/ Wirkstoffe so zu kombinieren, wie ich sie benötige. Das habe ich in einer Creme bisher nicht gefunden.', 'Christin Menke', 'christin.menke@gmx.de', 'approved', '2022-05-29 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Liebes Herbsom-Team!
Seit Jahren suche ich die perfekte Creme für mich! Meine Haut ist sehr trocken und aufgrund meines Alters auch faltig. Ich habe viel ausprobiert und dachte, es wäre unmöglich, irgendwie fehlte mir immer etwas.
Jetzt bin ich total zufrieden. Meine Faltentiefe ist tatsächlich weniger geworden und meine Haut fühlt sich samtig und ausgeglichen an.
Jeder sollte sich so wohl in seiner Haut fühlen!
DANKESCHÖN für diese tolle Creme😍', 'Barbara Klemm', 'klemm.barbara@googlemail.com', 'approved', '2022-06-03 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Wunderbares Produkt, was ich jederzeit nachkaufen würde! Außerdem möchte ich den tollen Service loben! Nachdem meine erste Bestellung leider geklaut wurde bzw. nicht angekommen ist, wurde mir sofort eine neue Bestellung via Gutschein zugesendet. Das war wahnsinnig freundlich und vor allem sehr kulant - vielen Dank dafür!', 'Laura Hohlfeldt', 'la.hohlfeldt@web.de', 'approved', '2022-06-23 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Ich habe jahrelang gar keine Hautcreme benutzt und merke erst jetzt wie gut das meiner Haut tut. Nach wenigen Wochen ist das jetzt ein ganz anderes Hautgefühl. Danke :)', 'Karl Fesenmeyer', 'karl.fesenmeyer@imap.de', 'approved', '2022-04-25 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Beste Creme! Nie wieder ohne ❤️', 'Stefanie Fuhrberg', 'stefanie.fuhrberg@web.de', 'approved', '2022-04-26 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
VALUES ('creme', 5, 'Gute Bewertung', 'Ich benutze die Creme seit mittlerweile drei Wochen und bin mega happy :) Ich habe vorher noch nie so viel Geld für die Hautpflege ausgegeben, aber das Konzept von Herbsom, dass man eine exakt auf die eigenen Bedürfnisse zugeschnittene Creme erhält, hat mich überzeugt. Nach den drei Wochen sehe ich schon einige Veränderungen. Meine Haut ist insgesamt glatter und strahlender und auch die Poren haben sich verkleinert. Genau das wollte ich erreichen. Ich kann die Creme deshalb guten Gewissens weiterempfehlen :)
Das Unpacking und Zusammenrühren der Creme hat übrigens auch viel Spaß gemacht!', 'Louisa Balster', 'louisabalster@web.de', 'approved', '2022-05-09 22:00:00', 0, 0);
INSERT INTO reviews (productId, rating, title, text, authorName, authorEmail, status, createdAt, helpfulCount, unhelpfulCount) 
